static bool Transfer(ref ImmutableState s, long from, long to, long amt) {
    for (;;) {
        var snapshot = Volatile.Read(ref s);
        if (snapshot.Balances[from] < amt) return false;
        var next = snapshot with {
            Balances = snapshot.Balances
                .SetItem(from, snapshot.Balances[from] - amt)
                .SetItem(to,   snapshot.Balances[to]   + amt)
        };
        if (ReferenceEquals(Interlocked.CompareExchange(ref s, next, snapshot), snapshot))
            return true;
        // conflict: the whole block replays against the new snapshot
    }
}
